CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
-- PostgreSQL 18 MVP schema draft for Planna; reconcile with future EF Core migrations.
-- This file is a design baseline, not an executed .NET migration or production script.
-- UUID generated by clients for offline entities; service can use gen_random_uuid() for internal IDs.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 email text NOT NULL,
 timezone text NOT NULL DEFAULT 'Asia/Shanghai',
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 deleted_at timestamptz,
 CONSTRAINT ck_email_length CHECK(length(email) BETWEEN 3 AND 320)
);
CREATE UNIQUE INDEX uq_users_email_ci ON users (lower(email)) WHERE deleted_at IS NULL;

-- Serialization point for per-owner committed sync cursor.
CREATE TABLE owner_sync_clocks (
 owner_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 revision bigint NOT NULL DEFAULT 0 CHECK(revision >= 0),
 min_available_revision bigint NOT NULL DEFAULT 0 CHECK(min_available_revision >= 0)
);

CREATE TABLE device_sessions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 device_name text NOT NULL,
 platform text NOT NULL CHECK(platform IN ('android','ios','windows','macos','linux')),
 refresh_token_hash text NOT NULL UNIQUE,
 last_seen_at timestamptz,
 revoked_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_device_sessions_user ON device_sessions(user_id, created_at DESC);

CREATE TABLE task_lists (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),
 kind text NOT NULL DEFAULT 'custom' CHECK(kind IN ('inbox','custom')),
 sort_order numeric(30,10) NOT NULL DEFAULT 0,
 archived_at timestamptz,
 version bigint NOT NULL DEFAULT 1 CHECK(version >= 1),
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 deleted_at timestamptz,
 UNIQUE(owner_id,id)
);
CREATE UNIQUE INDEX uq_owner_inbox ON task_lists(owner_id) WHERE kind='inbox' AND deleted_at IS NULL;
CREATE INDEX idx_list_owner_order ON task_lists(owner_id,sort_order) WHERE deleted_at IS NULL;

CREATE TABLE tasks (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 list_id uuid NOT NULL,
 title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 500),
 description text NOT NULL DEFAULT '' CHECK(length(description)<=20000),
 status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','done','archived')),
 priority smallint NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 3),
 start_at timestamptz,
 due_at timestamptz,
 due_local_date date,
 all_day boolean NOT NULL DEFAULT false,
 time_zone text NOT NULL DEFAULT 'Asia/Shanghai',
 estimate_minutes smallint CHECK(estimate_minutes BETWEEN 1 AND 1440),
 position numeric(30,10) NOT NULL DEFAULT 0,
 completed_at timestamptz,
 version bigint NOT NULL DEFAULT 1 CHECK(version>=1),
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 deleted_at timestamptz,
 FOREIGN KEY (owner_id,list_id) REFERENCES task_lists(owner_id,id),
 UNIQUE(owner_id,id),
 CONSTRAINT ck_due_kind CHECK ((all_day = true AND due_at IS NULL) OR (all_day = false AND due_local_date IS NULL)),
 CONSTRAINT ck_due_after_start CHECK (due_at IS NULL OR start_at IS NULL OR due_at>=start_at)
);
CREATE INDEX idx_tasks_owner_due ON tasks(owner_id,due_at) WHERE deleted_at IS NULL;
CREATE INDEX idx_tasks_owner_status ON tasks(owner_id,status,updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_tasks_list_position ON tasks(owner_id,list_id,position) WHERE deleted_at IS NULL;

CREATE TABLE task_steps (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL,
 task_id uuid NOT NULL,
 title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 500),
 is_done boolean NOT NULL DEFAULT false,
 position numeric(30,10) NOT NULL DEFAULT 0,
 version bigint NOT NULL DEFAULT 1 CHECK(version>=1),
 deleted_at timestamptz,
 FOREIGN KEY (owner_id,task_id) REFERENCES tasks(owner_id,id)
);
CREATE INDEX idx_task_steps_task ON task_steps(task_id,position);

CREATE TABLE tags (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 60),
 color text,
 version bigint NOT NULL DEFAULT 1,
 deleted_at timestamptz,
 UNIQUE(owner_id,id)
);
CREATE UNIQUE INDEX uq_tags_owner_name ON tags(owner_id,lower(name)) WHERE deleted_at IS NULL;

CREATE TABLE task_tags (
 owner_id uuid NOT NULL,
 task_id uuid NOT NULL,
 tag_id uuid NOT NULL,
 PRIMARY KEY(owner_id,task_id,tag_id),
 FOREIGN KEY (owner_id,task_id) REFERENCES tasks(owner_id,id),
 FOREIGN KEY (owner_id,tag_id) REFERENCES tags(owner_id,id)
);

CREATE TABLE recurrences (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL,
 task_id uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN ('rrule','after_completion','legal_workday')),
 rrule text,
 interval_days int,
 dtstart_local timestamp without time zone NOT NULL,
 time_zone text NOT NULL,
 enabled boolean NOT NULL DEFAULT true,
 version bigint NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(owner_id,task_id),
 FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id),
 CONSTRAINT ck_recur_fields CHECK ((kind='rrule' AND rrule IS NOT NULL AND interval_days IS NULL)
   OR (kind='after_completion' AND interval_days BETWEEN 1 AND 3650 AND rrule IS NULL)
   OR (kind='legal_workday' AND rrule IS NULL AND interval_days IS NULL))
);

CREATE TABLE task_occurrences (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL,
 series_task_id uuid NOT NULL,
 original_local_start timestamp without time zone NOT NULL,
 time_zone text NOT NULL,
 due_at timestamptz,
 status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','done','skipped')),
 completed_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 version bigint NOT NULL DEFAULT 1,
 UNIQUE(series_task_id,original_local_start),
 UNIQUE(owner_id,id),
 FOREIGN KEY(owner_id,series_task_id) REFERENCES tasks(owner_id,id)
);
CREATE INDEX idx_occ_owner_due ON task_occurrences(owner_id,due_at);

CREATE TABLE reminders (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL,
 task_id uuid NOT NULL,
 occurrence_id uuid,
 channel text NOT NULL DEFAULT 'local' CHECK(channel IN ('local','push','in_app')),
 scheduled_at timestamptz NOT NULL,
 offset_minutes integer,
 enabled boolean NOT NULL DEFAULT true,
 version bigint NOT NULL DEFAULT 1,
 deleted_at timestamptz,
 FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id),
 FOREIGN KEY(owner_id,occurrence_id) REFERENCES task_occurrences(owner_id,id)
);
CREATE INDEX idx_reminders_owner_schedule ON reminders(owner_id,scheduled_at) WHERE enabled=true AND deleted_at IS NULL;

CREATE TABLE task_time_blocks (
 id uuid PRIMARY KEY,
 owner_id uuid NOT NULL,
 task_id uuid NOT NULL,
 start_at timestamptz NOT NULL,
 end_at timestamptz NOT NULL,
 is_locked boolean NOT NULL DEFAULT false,
 version bigint NOT NULL DEFAULT 1,
 deleted_at timestamptz,
 FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id),
 CHECK(end_at>start_at)
);
CREATE INDEX idx_time_blocks_owner_start ON task_time_blocks(owner_id,start_at) WHERE deleted_at IS NULL;

-- Every user mutation transaction must lock owner_sync_clocks row, advance revision,
-- then insert changes in the same transaction before commit. Do NOT rely on bare BIGSERIAL commit ordering.
CREATE TABLE sync_changes (
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 revision bigint NOT NULL CHECK(revision>0),
 change_index integer NOT NULL DEFAULT 0 CHECK(change_index>=0),
 entity_type text NOT NULL,
 entity_id uuid NOT NULL,
 op text NOT NULL CHECK(op IN ('upsert','delete')),
 entity_version bigint NOT NULL,
 payload jsonb,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(owner_id,revision,change_index)
);
CREATE INDEX idx_sync_changes_owner_rev ON sync_changes(owner_id,revision,change_index);

CREATE TABLE client_mutations (
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 mutation_id uuid NOT NULL,
 device_id uuid,
 request_hash text NOT NULL,
 response jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(owner_id,mutation_id)
);
CREATE INDEX idx_mutations_created ON client_mutations(created_at);

CREATE TABLE ai_consents (
 owner_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 allowed_scopes text[] NOT NULL DEFAULT ARRAY[]::text[],
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ai_plans (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','validated','awaiting_confirmation','applied','expired','rejected','failed')),
 snapshot_hash text NOT NULL,
 operations jsonb NOT NULL,
 expires_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 applied_at timestamptz
);
CREATE INDEX idx_ai_plans_owner ON ai_plans(owner_id,created_at DESC);

CREATE TABLE ai_action_audits (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 plan_id uuid REFERENCES ai_plans(id),
 action_type text NOT NULL,
 target_id uuid NOT NULL,
 before_value jsonb,
 after_value jsonb,
 actor text NOT NULL CHECK(actor IN ('user','ai_confirmed')),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ai_audit_owner_time ON ai_action_audits(owner_id,created_at DESC);

CREATE TABLE scheduled_jobs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 job_type text NOT NULL,
 dedupe_key text NOT NULL UNIQUE,
 payload jsonb NOT NULL,
 run_at timestamptz NOT NULL,
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','succeeded','dead','cancelled')),
 attempts integer NOT NULL DEFAULT 0,
 locked_until timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_jobs_ready ON scheduled_jobs(run_at) WHERE status='pending';

-- IMPORTANT: Init must seed one Inbox and owner_sync_clocks entry per new user,
-- via the register transaction in the application service; do not insert fake users here.


INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('202611030001_BaselineSchema', '10.0.14');

COMMIT;

START TRANSACTION;
ALTER TABLE ai_plans ADD confirmation_token_hash text;

ALTER TABLE task_steps ADD estimate_minutes smallint;

ALTER TABLE task_steps ADD CONSTRAINT ck_task_steps_estimate_minutes CHECK (estimate_minutes BETWEEN 1 AND 1440);

CREATE TABLE ai_breakdown_drafts (
    id uuid NOT NULL DEFAULT (gen_random_uuid()),
    owner_id uuid NOT NULL,
    task_id uuid NOT NULL,
    task_version bigint NOT NULL,
    status text NOT NULL DEFAULT 'awaiting_confirmation',
    snapshot_hash text NOT NULL,
    steps jsonb NOT NULL,
    assumptions jsonb NOT NULL DEFAULT ('[]'::jsonb),
    confirmation_token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT (now()),
    applied_at timestamp with time zone,
    CONSTRAINT pk_ai_breakdown_drafts PRIMARY KEY (id),
    CONSTRAINT ak_ai_breakdown_drafts_owner_id_id UNIQUE (owner_id, id),
    CONSTRAINT ck_ai_breakdown_task_version CHECK (task_version >= 1),
    CONSTRAINT ck_ai_breakdown_status CHECK (status IN ('awaiting_confirmation','applied','expired','rejected')),
    CONSTRAINT ck_ai_breakdown_steps CHECK (jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) BETWEEN 1 AND 20),
    CONSTRAINT ck_ai_breakdown_assumptions CHECK (jsonb_typeof(assumptions) = 'array'),
    CONSTRAINT fk_ai_breakdown_drafts_users FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_breakdown_drafts_tasks FOREIGN KEY (owner_id, task_id) REFERENCES tasks (owner_id, id)
);

CREATE INDEX idx_ai_breakdowns_owner_task ON ai_breakdown_drafts (owner_id, task_id, created_at DESC);

CREATE TABLE account_exports (
    id uuid NOT NULL DEFAULT (gen_random_uuid()),
    owner_id uuid NOT NULL,
    status text NOT NULL DEFAULT 'pending',
    snapshot_at timestamp with time zone,
    storage_key text,
    error_code text,
    requested_at timestamp with time zone NOT NULL DEFAULT (now()),
    ready_at timestamp with time zone,
    expires_at timestamp with time zone,
    CONSTRAINT pk_account_exports PRIMARY KEY (id),
    CONSTRAINT ak_account_exports_owner_id_id UNIQUE (owner_id, id),
    CONSTRAINT ck_account_exports_status CHECK (status IN ('pending','ready','failed','expired')),
    CONSTRAINT ck_account_exports_ready CHECK ((status = 'ready' AND storage_key IS NOT NULL AND ready_at IS NOT NULL AND expires_at IS NOT NULL) OR status <> 'ready'),
    CONSTRAINT fk_account_exports_users FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_account_exports_owner_time ON account_exports (owner_id, requested_at DESC);

CREATE TABLE account_deletion_requests (
    id uuid NOT NULL DEFAULT (gen_random_uuid()),
    owner_id uuid NOT NULL,
    status text NOT NULL DEFAULT 'accepted',
    policy_version text NOT NULL,
    requested_at timestamp with time zone NOT NULL DEFAULT (now()),
    completed_at timestamp with time zone,
    last_error_code text,
    CONSTRAINT pk_account_deletion_requests PRIMARY KEY (id),
    CONSTRAINT ak_account_deletion_requests_owner_id UNIQUE (owner_id),
    CONSTRAINT ck_account_deletion_requests_status CHECK (status IN ('accepted','purging','completed','failed')),
    CONSTRAINT fk_account_deletion_requests_users FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE
);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('202611030002_Spec01Contracts', '10.0.14');

COMMIT;

START TRANSACTION;
CREATE TABLE auth_login_challenges (
    id uuid NOT NULL DEFAULT (gen_random_uuid()),
    email text NOT NULL,
    request_key uuid NOT NULL,
    code_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT (now()),
    consumed_at timestamp with time zone,
    attempts integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_auth_login_challenges PRIMARY KEY (id),
    CONSTRAINT ck_auth_login_challenges_attempts CHECK (attempts BETWEEN 0 AND 5)
);

CREATE INDEX idx_auth_challenges_email_created ON auth_login_challenges (email, created_at DESC);

CREATE UNIQUE INDEX uq_auth_challenges_request ON auth_login_challenges (email, request_key);

CREATE TABLE refresh_token_history (
    token_hash text NOT NULL,
    session_id uuid NOT NULL,
    consumed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL DEFAULT (now()),
    CONSTRAINT pk_refresh_token_history PRIMARY KEY (token_hash),
    CONSTRAINT fk_refresh_token_history_session FOREIGN KEY (session_id) REFERENCES device_sessions (id) ON DELETE CASCADE
);

CREATE INDEX idx_refresh_token_history_session ON refresh_token_history (session_id);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('202611040003_AuthSessions', '10.0.14');

